func TestPolylineRoundTrip(t *testing.T) {
	ls := orb.LineString{{12.80001, 48.20001}, {12.8, 48.2}, {-0.00001, -0.00001}, {179.99999, -89.99999}}
	got, err := DecodePolyline(EncodePolyline(ls))
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != len(ls) {
		t.Fatalf("len %d", len(got))
	}
	for i := range ls {
		if math.Abs(got[i].Lat()-ls[i].Lat()) > 1e-9 || math.Abs(got[i].Lon()-ls[i].Lon()) > 1e-9 {
			t.Errorf("point %d: %v, want %v", i, got[i], ls[i])
		}
	}
}

